+    readonly expected: string;
+    readonly replacement: string;
+  }) => Effect.Effect<void, WorkspaceViolation | WorkspaceOperationFailure>;
+  readonly inspectPatch: Effect.Effect<PatchSnapshot, WorkspaceOperationFailure>;
